INSERT INTO `pages` VALUES (1,'Homepage','[hero-banner style=\"1\" title=\"We Create Digital Experiences\" subtitle=\"B2B Marketing Agency\" description=\"We help brands grow through creative strategy, bold design, and digital innovation.\" background_image=\"pages/bg-img.webp\" image=\"pages/img-1.webp\" background_video=\"/themes/orisa/videos/video-1.mp4\" primary_action_label=\"Explore All Work\" primary_action_url=\"/portfolio\" primary_action_icon=\"ti ti-arrow-up-right\" secondary_action_label=\"How We Work\" secondary_action_url=\"/about-1\" secondary_action_icon=\"ti ti-phone\"][/hero-banner]\n[about-us-information style=\"1\" title=\"We shape animated stories that inspire and engage, uniting thoughtful design, fluid motion, and digital craftsmanship.\" subtitle=\"About Us\" description=\"We build &lt;b&gt;bold&lt;/b&gt;, resilient brands designed to leave a lasting mark on the world.\" primary_action_label=\"GET IN TOUCH\" primary_action_url=\"/contact-1\" avatars_quantity=\"5\" avatars_image_1=\"testimonials/avatar-1.webp\" avatars_image_2=\"testimonials/avatar-2.webp\" avatars_image_3=\"testimonials/avatar-3.webp\" avatars_image_4=\"testimonials/avatar-4.webp\" avatars_image_5=\"testimonials/avatar-5.webp\" experience_years=\"15\" quantity=\"2\" title_1=\"Creative Expertise\" description_1=\"With over a decade of design expertise, we create tailored solutions that engage audiences, build meaningful connections, and elevate brands with creativity and intent.\" image_1=\"pages/img-3.webp\" style_image_1=\"pages/img-3.webp\" title_2=\"Experience &amp; Innovation\" description_2=\"Backed by a decade of creative experience, we craft visual experiences that bring together strategy, design, and technology to grow brands, inspire audiences, and create meaningful impact.\" image_2=\"pages/img-4.webp\" style_image_2=\"pages/img-4.webp\"][/about-us-information]\n[partners style=\"1\" quantity=\"10\" name_1=\"Framer\" image_1=\"partners/1.webp\" url_1=\"https://google.com\" open_in_new_tab_1=\"1\" name_2=\"Reddit\" image_2=\"partners/2.webp\" url_2=\"https://google.com\" open_in_new_tab_2=\"1\" name_3=\"Netflix\" image_3=\"partners/3.webp\" url_3=\"https://google.com\" open_in_new_tab_3=\"1\" name_4=\"Microsoft\" image_4=\"partners/4.webp\" url_4=\"https://google.com\" open_in_new_tab_4=\"1\" name_5=\"Discover\" image_5=\"partners/5.webp\" url_5=\"https://google.com\" open_in_new_tab_5=\"1\" name_6=\"Lemon Squeezy\" image_6=\"partners/6.webp\" url_6=\"https://google.com\" open_in_new_tab_6=\"1\" name_7=\"PayPal\" image_7=\"partners/7.webp\" url_7=\"https://google.com\" open_in_new_tab_7=\"1\" name_8=\"Mailchimp\" image_8=\"partners/8.webp\" url_8=\"https://google.com\" open_in_new_tab_8=\"1\" name_9=\"Shopify\" image_9=\"partners/6.webp\" url_9=\"https://google.com\" open_in_new_tab_9=\"1\" name_10=\"Slack\" image_10=\"partners/5.webp\" url_10=\"https://google.com\" open_in_new_tab_10=\"1\"][/partners]\n[services style=\"1\" subtitle=\"OUR SOLUTIONS\" description=\"Since 2012\" service_ids=\"1,2,3,4\" experience_years=\"38\"][/services]\n[projects style=\"1\" title=\"Selected work we\'re proud of\" subtitle=\"Portfolio\" description=\"A curated selection of projects where strategy, creativity, and craftsmanship come together to build meaningful and enduring brand experiences.\" primary_action_label=\"View latest projects\" primary_action_url=\"/portfolio\"][/projects]\n[testimonials style=\"1\" title=\"Trusted by Clients\" subtitle=\"Real client experiences that speak to the strength of our work.\" quantity=\"6\" name_1=\"Lucas Moreno\" role_1=\"Product Manager\" company_1=\"Barcelona, Spain\" quote_1=\"The collaboration was seamless from start to finish. Their UX decisions significantly improved our product...\" rating_1=\"4\" avatar_1=\"general/testimonial-avatar-1.webp\" company_logo_1=\"general/testimonial-logo-architect.webp\" name_2=\"Hannah Lee\" role_2=\"Creative Director\" company_2=\"Studio Kinetic\" quote_2=\"A rare 