INSERT INTO `pf_packages_translations` VALUES ('ar',1,'الخطة التجريبية','حزمة تجريبية مجانية','','0',NULL,'+عضو واحد\n+ أكثر من 1200 قطعة لواجهة المستخدم\n+10 جيجابايت تخزين سحابي\n- حساب البريد الإلكتروني الشخصي\n-أولوية الدعم','يبدأ','/contact'),('ar',2,'معيار','مناسبة للمجموعات الكبيرة','','49 دولارًا','441 دولارًا','+05 أعضاء\n+ جميع قنوات الوسائط المتعددة\n+ جميع ميزات إدارة علاقات العملاء (CRM) المتقدمة\n+ ما يصل إلى 15000 جهة اتصال\nدعم +24/7 (البريد الإلكتروني، الدردشة)','يبدأ','/contact'),('ar',3,'عمل','مشروع متقدم','','69 دولارًا','621 دولارًا','+50 عضوا\n+ أكثر من 1500 قطعة لواجهة المستخدم\n+100 جيجابايت تخزين سحابي\n+ حساب البريد الإلكتروني الشخصي\n+ دعم الأولوية','يبدأ','/contact'),('ar',4,'مَشرُوع','للشركات الكبيرة','','99 دولارًا','891 دولارًا','+ ميزات التخصيص\n+ قابلية التوسع والأمن\n+إدارة الحساب\n+ سجل دردشة غير محدود\n+50 التكامل','يبدأ','/contact'),('fr',1,'Plan d\'essai','Forfait d\'essai gratuit','','0',NULL,'+Un membre\n+Plus de 1200 blocs d\'interface utilisateur\n+10 Go de stockage cloud\n-Compte de messagerie personnel\n-Support prioritaire','Commencer','/contact'),('fr',2,'Standard','Convient aux grands groupes','','49 $','441 $','+05 Membres\n+Toutes les chaînes multimédia\n+Toutes les fonctionnalités CRM avancées\n+Jusqu\'à 15 000 contacts\nAssistance +24h/24 et 7j/7 (e-mail, chat)','Commencer','/contact'),('fr',3,'Entreprise','Projet avancé','','69 $','621 $','+50 Membres\n+Plus de 1500 blocs d\'interface utilisateur\n+100 Go de stockage cloud\n+Compte de messagerie personnel\n+Assistance prioritaire','Commencer','/contact'),('fr',4,'Entreprise','Pour les grandes entreprises','','99 $','891 $','+Customization features\n+ Scalability & security\n+Gestion de compte\n+Unlimited chat history\n+50 Intégration','Commencer','/contact'),('id',1,'Rencana Percobaan','Paket uji coba gratis','','0',NULL,'+Satu anggota\n+Lebih dari 1200 blok UI\nPenyimpanan awan +10 GB\n-Akun email pribadi\n-Dukungan prioritas','Mulai','/contact'),('id',2,'Standar','Cocok untuk kelompok besar','','$49','$441','+05 Anggota\n+Semua saluran multimedia\n+Semua fitur CRM tingkat lanjut\n+Hingga 15.000 kontak\n+ Dukungan 24/7 (Email, Obrolan)','Mulai','/contact'),('id',3,'Bisnis','Proyek lanjutan','','$69','$621','+50 Anggota\n+Lebih dari 1500 blok UI\nPenyimpanan awan +100 GB\n+Akun email pribadi\n+Dukungan prioritas','Mulai','/contact'),('id',4,'Perusahaan','Untuk perusahaan besar','','$99','$891','+Fitur penyesuaian\n+ Skalabilitas & keamanan\n+Manajemen akun\n+Riwayat obrolan tidak terbatas\n+50 Integrasi','Mulai','/contact'),('tr',1,'Deneme Planı','Ücretsiz deneme paketi','','0',NULL,'+Bir üye\n+1200\'den fazla kullanıcı arayüzü bloğu\n+10 GB bulut depolama alanı\n-Kişisel e-posta hesabı\n-Öncelikli destek','Başlamak','/contact'),('tr',2,'Standart','Büyük gruplara uygun','','49$','441$','+05 Üye\n+Tüm multimedya kanalları\n+Tüm gelişmiş CRM özellikleri\n+15.000\'e kadar kişi\n+7/24 destek (E-posta, Sohbet)','Başlamak','/contact'),('tr',3,'İşletme','Gelişmiş proje','','69$','621 dolar','+50 Üye\n+1500\'den fazla kullanıcı arayüzü bloğu\n+100 GB cloud storage\n+Kişisel e-posta hesabı\n+Öncelikli destek','Başlamak','/contact'),('tr',4,'Girişim','Büyük şirketler için','','99 dolar','891 dolar','+Özelleştirme özellikleri\n+ Ölçeklenebilirlik ve güvenlik\n+Account management\n+Sınırsız sohbet geçmişi\n+50 Entegrasyon','Başlamak','/contact'),('vi',1,'Gói dùng thử','Gói dùng thử miễn phí','','0',NULL,'+Một thành viên\n+Hơn 1200 khối UI\n+10 GB lưu trữ đám mây\n-Tài khoản email cá nhân\n-Hỗ trợ ưu tiên','Bắt đầu','/contact'),('vi',2,'Tiêu chuẩn','Phù hợp cho nhóm lớn','','$49','$441','+05 Thành viên\n+Tất cả kênh đa phương tiện\n+Tất cả tính năng CRM nâng cao\n+Tối đa 15.000 liên hệ\n+Hỗ trợ 24/7 (Email, Chat)','Bắt đầu','/contact'),('vi',3,'Doanh nghiệp','Dự án nâng cao','','$69','$621','+50 Thành viên\n+Hơn 1500 khối UI\n+100 GB lưu trữ đám mây\n+Tài khoản email cá nhân\n+Hỗ trợ ưu tiên','Bắt đầu','/contact'),('vi',4,'Doanh nghiệp lớn','Cho công ty lớn','','$99','$891','+Tính năng tùy chỉnh\n+Khả năng mở rộng & bảo mật\n+Quản lý tài khoản\n+Lịch sử chat không giới hạn\n+50 Tích hợp','Bắt đầu','/contact');
